#include <iostream>
#include <string>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    string expr;
    cin >> N >> expr;
    // First pass: handle all * (higher precedence)
    // Stack-based: numbers with + between them
    ll ans = 0;
    ll cur = 0;
    char prev_op = '+';
    for (int i = 0; i < N; i++)
    {
        int num = expr[i * 2] - '0';
        if (prev_op == '+')
        {
            ans = (ans + cur) % MOD;
            cur = num;
        }
        else // '*'
        {
            cur = (cur * num) % MOD;
        }
        if (i < N - 1)
            prev_op = expr[i * 2 + 1];
    }
    ans = (ans + cur) % MOD;
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <climits>
using namespace std;

int main()
{
    string src, dst;
    cin >> src >> dst;
    int n = src.size();
    int ans = INT_MAX;

    auto flip = [&](string &s, int i)
    {
        s[i] = (s[i] == '0') ? '1' : '0';
        if (i > 0)
            s[i - 1] = (s[i - 1] == '0') ? '1' : '0';
        if (i < n - 1)
            s[i + 1] = (s[i + 1] == '0') ? '1' : '0';
    };

    // Try the two possibilities for the first button
    for (int first = 0; first <= 1; first++)
    {
        string cur = src;
        int cnt = 0;
        if (first)
        {
            flip(cur, 0);
            cnt++;
        }
        for (int i = 1; i < n; i++)
        {
            if (cur[i - 1] != dst[i - 1])
            {
                flip(cur, i);
                cnt++;
            }
        }
        if (cur == dst)
            ans = min(ans, cnt);
    }
    if (ans == INT_MAX)
        cout << "impossible" << endl;
    else
        cout << ans << endl;
    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;

int light[7][8], press[7][8];

int solve()
{
    // Try all 2^6 = 64 possibilities for first row
    for (int s = 0; s < (1 << 6); s++)
    {
        memset(press, 0, sizeof(press));
        for (int j = 0; j < 6; j++)
            if (s >> j & 1)
                press[1][j + 1] = 1;

        for (int i = 1; i <= 5; i++)
        {
            for (int j = 1; j <= 6; j++)
            {
                int cur = light[i][j] ^ press[i][j] ^ press[i][j - 1] ^ press[i][j + 1] ^ press[i - 1][j];
                press[i + 1][j] = cur;
            }
        }

        bool ok = true;
        for (int j = 1; j <= 6; j++)
            if (light[5][j] ^ press[5][j] ^ press[5][j - 1] ^ press[5][j + 1] ^ press[4][j])
            {
                ok = false;
                break;
            }
        if (ok)
            return s;
    }
    return -1;
}

int main()
{
    int T;
    cin >> T;
    for (int t = 1; t <= T; t++)
    {
        memset(light, 0, sizeof(light));
        for (int i = 1; i <= 5; i++)
            for (int j = 1; j <= 6; j++)
                cin >> light[i][j];

        int s = solve();
        cout << "PUZZLE #" << t << endl;
        for (int i = 1; i <= 5; i++)
        {
            for (int j = 1; j <= 6; j++)
            {
                if (s >= 0)
                    cout << press[i][j];
                else
                    cout << 0;
                if (j < 6)
                    cout << " ";
            }
            cout << " " << endl;
        }
    }
    return 0;
}

