void mergesort(int num[],int l,int r)
{
    int mid=l+r>>1;
    if(l>=r) return;
    mergesort(num,l,mid);
    mergesort(num,mid+1,r);
    int k=0;
    int p=l,q=mid+1;
    while(p<=mid&&q<=r)
    {
        if(num[p]<=num[q])
            temp[k++]=num[p++];
